import hashlib
import hmac
import secrets
import time


class AccountService:
    def __init__(self) -> None:
        self._accounts = {}
        self._reset_tokens = {}

    @staticmethod
    def _hash_password(password: str, salt: bytes) -> bytes:
        return hashlib.pbkdf2_hmac(
            "sha256", password.casefold().encode("utf-8"), salt, 200_000
        )

    def register(
        self,
        email: str,
        password: str,
        is_admin: bool = False,
        display_name: str = "",
    ) -> None:
        email = email.casefold()
        if email in self._accounts:
            raise ValueError("Account already exists")
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters")

        salt = secrets.token_bytes(16)
        self._accounts[email] = {
            "salt": salt,
            "password_hash": self._hash_password(password, salt),
            "is_admin": is_admin,
            "display_name": display_name,
            "last_login": None,
        }

    def display_name(self, email: str) -> str:
        return self._accounts[email.casefold()]["display_name"]

    def list_users(self) -> list[str]:
        return sorted(self._accounts)

    def last_login(self, email: str) -> float | None:
        return self._accounts[email.casefold()]["last_login"]

    def login(self, email: str, password: str) -> bool:
        account = self._accounts.get(email.casefold())
        if account is None:
            return False
        password_hash = self._hash_password(password, account["salt"])
        if not hmac.compare_digest(password_hash, account["password_hash"]):
            return False
        account["last_login"] = time.time()
        return True

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        requester = self._accounts.get(requester_email.casefold())
        if requester is None or not requester["is_admin"]:
            raise PermissionError("Only administrators can request password resets")

        target_email = target_email.casefold()
        if target_email not in self._accounts:
            raise ValueError("Target account does not exist")

        token = secrets.token_urlsafe(32)
        while token in self._reset_tokens:
            token = secrets.token_urlsafe(32)
        self._reset_tokens[token] = target_email
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        target_email = self._reset_tokens.get(token)
        if target_email is None:
            raise ValueError("Invalid or already used reset token")
        if len(new_password) < 8:
            raise ValueError("Password must be at least 8 characters")

        salt = secrets.token_bytes(16)
        password_hash = self._hash_password(new_password, salt)
        account = self._accounts[target_email]
        account["salt"] = salt
        account["password_hash"] = password_hash
        del self._reset_tokens[token]
